INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(66695, 'esES', 'Destino tentador: Sepulcro de los Primeros', '', '', '', '', '', '', '', '', 45114),
(66694, 'esES', 'Destino tentador: Sagrario de Dominación', '', '', '', '', '', '', '', '', 45114),
(66661, 'esES', 'Es solo una moneda, ¿qué puede valer?', 'Busca a un especulador en Oribos para obtener información.', '<Este curioso objeto plantea más preguntas que respuestas. ¿Cómo lo has conseguido? ¿Para qué se usa? ¿Es peligroso?>\n\n<Si la Ciudad Eterna no tiene las respuestas, los Especuladores que comercian allí seguro que saben algo>.', '', '', '', '', '', '', 45114),
(66649, 'esES', 'La rueda del destino', 'Derrota a $1oa jefes de bandas predestinadas distintos.', '<Gracias al sinfín de pruebas que has superado, notas que el poder aumenta en tu interior. Sea cual sea el origen de estas anomalías, ahora te consuelan en lugar de confundirte>.\n\n<Adéntrate en la incertidumbre una vez más, lucha contra la oscuridad y abraza el destino>.', '', '', '', '', '', '', 45114),
(66648, 'esES', 'Cruce del destino', 'Derrota a 30 jefes de bandas predestinadas distintos.', '<La realidad da vueltas tu alrededor. Tus recuerdos sobre este lugar se nublan y cambian intensamente a cada instante. Algo ha cambiado>.\n\n<Tienes la certeza de que, a pesar de las similitudes, no es el lugar que conocías. No del todo>.\n\n<De todos modos, te aguarda el camino. Ni el engaño ni la distorsión retrasarán tu destino>.', '', '', '', '', '', '', 45114),
(66619, 'esES', 'Antros', '', '', '', '', '', '', '', '', 45114),
(66618, 'esES', 'Mor\'geth', '', '', '', '', '', '', '', '', 45114),
(65411, 'esES', 'Una situación desconcertante', '', '', '', '', '', '', '', '', 45114),
(54478, 'esES', 'Métodos de inscripción', '', '', '', '', '', '', '', '', 45114),
(54474, 'esES', 'Fórmulas encantadas', '', '', '', '', '', '', '', '', 45114),
(54391, 'esES', 'Donaciones de Costa Oscura: berilio dorado rápido', 'Reúne $1oa lomos adobados para Senedras, que está en el Puerto de Boralus.', 'Una buena y sustanciosa carne aporta el alimento que nuestros aliados merecen antes de partir hacia la batalla, por no mencionar que además da para un caldo de rechupete, cosa que nuestras tropas parecen apreciar cuando los vientos soplan fuerte y el frío de la noche flota en el aire.\n\nSi me traes lomo recién adobado será para mí un placer pasárselo a nuestros oficiales de suministros.', '', '', '', '', '', '', 45114),
(54381, 'esES', 'Donaciones de Costa Oscura: tinta ultramarina', 'Reúne $1oa siluros a la parrilla para Senedras, que está en el Puerto de Boralus.', 'Saludos, $gviajero:viajera;.\n\nMe pidieron que me asegurara de que nunca faltaran suministros de comida, y últimamente las provisiones de pescado escasean. ¿Tienes algo que quisieras donar?', '', '', '', '', '', '', 45114),
(54048, 'esES', 'Matar a una celadora', 'Derrota a Sira Guardaluna.', '<La opresiva sensación de que te persiguen ha alcanzado su punto álgido.\n\nSabes que hay alguien detrás de ti>.', '', 'Sira te ha estado buscando por toda Costa Oscura. Ha venido a resolver los asuntos pendientes.', 'Sira Guardaluna', '', '', '', 45114),
(53317, 'esES', 'Plata de tormenta densa', '', '', '', '', '', '', '', '', 45114),
(49053, 'esES', 'Vigía', '', '', '', '', '', '', '', '', 45114),
(41695, 'esES', 'PELIGRO: Defilia', '', '', '', '', '', '', '', '', 45114),
(6847, 'esES', 'El ojo que todo lo ve del maestro Ryson', 'Recupera el Ojo que todo lo ve del maestro Ryson en las cuevas de los Hacha Invernal y devuélveselo.$B$BPero ándate con cuidado, al parecer el Ojo que todo lo ve del maestro Ryson ¡está maldito!', 'Tu guerra en el corazón de Alterac no significa nada para la Hermandad, $c. Haremos lo que siempre hemos hecho: esperar hasta que un vencedor surja de las cenizas, acabe con toda esta locura y entonces dé el golpe definitivo.$B$BAunque no hemos venido para eso. El Ojo que todo lo ve se ha perdido, lo han arrebatado los trols Hacha Invernal de la región.$B$BRecupera el Ojo y nos pondremos a tu servicio por el tiempo que quede por tu favor.$B$BRegresa cuando consigas el Ojo para que pueda examinarte.$B$B<el maestro Ryson esboza una sonrisa>.', 'El ojo que todo lo ve del maestro Ryson recuperado', '', '', '', '', 'Vuelve con: Maestro de la Hermandad Ryson. Zona: Valle de Alterac.', 45114);

